
export type Reference = {
  id: string;
  name: string;
  subject: string;
  category: string;
  description: string;
  syntax: string;
  parameters: string[];
  example: string;
  output: string;
  explanation: string[];
  mistakes: string[];
  tags: string[];
  related: string[];
};

const make = (
  id: string,
  name: string,
  subject: string,
  category: string,
  description: string,
  syntax: string,
  example: string,
  output: string,
  explanation: string | string[],
  tags: string,
  related: string[] = []
): Reference => ({
  id,
  name,
  subject,
  category,
  description,
  syntax,
  parameters: [],
  example,
  output,
  explanation: Array.isArray(explanation) ? explanation : [explanation],
  mistakes: [
    "Check the input range and data types before applying the formula.",
    "Verify blanks, duplicates, and unexpected values in the source data."
  ],
  tags: tags.split(/\s+/).filter(Boolean),
  related
});

